import openpyxl

wb = openpyxl.load_workbook('gdp.xlsx', data_only=True)
print("Sheet names:", wb.sheetnames)

# Examine the Data sheet
ds = wb['Data']
print(f"\nData sheet dimensions: {ds.dimensions}")
print(f"Data sheet max_row={ds.max_row}, max_col={ds.max_column}")

print("\n--- Data sheet rows 1-5 (headers) ---")
for row in ds.iter_rows(min_row=1, max_row=5, values_only=False):
    for cell in row:
        if cell.value is not None:
            print(f"  {cell.coordinate}: {cell.value}")

print("\n--- Data sheet rows 20-40 ---")
